import { expect, test, type Page } from "@playwright/test";
import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import { launchPackagedApp, type LaunchedApp } from "./launch";

// Generated by `npm run fixtures`: an 8 s vertical clip.
const CLIP = path.resolve("fixtures", "vertical_1080x1920_30.mp4");
const FULL = "Levi's 501 Jeans";
const SLUG = "levis-501-jeans";
const BANK_TEXT = "I can't fix my smile";

let launched: LaunchedApp;
let page: Page;

test.beforeAll(async () => {
  test.skip(!existsSync(CLIP), 'Run "npm run fixtures" first.');
  launched = await launchPackagedApp();
  page = await launched.app.firstWindow();
});

test.afterAll(async () => {
  await launched?.app.close();
});

const nav = (name: string) =>
  page.getByRole("button", { name, exact: true }).first().click();
const slot = (name: "before" | "after" | "broll") =>
  page.getByTestId(`slot-${name}`);
const exportButton = () =>
  page.getByRole("button", { name: "Export", exact: true });

// Fills Before and After with the fixture, picks the product's b-roll and a bank caption on
// the Before clip.
async function buildVideo(): Promise<void> {
  await page.getByLabel("Before clip file").setInputFiles([CLIP]);
  await page.getByLabel("After clip file").setInputFiles([CLIP]);
  await expect(slot("before")).toHaveAttribute("data-status", "ready", {
    timeout: 90_000,
  });
  await expect(slot("after")).toHaveAttribute("data-status", "ready", {
    timeout: 90_000,
  });
  // One slot still empty: Export is off and says why.
  await expect(exportButton()).toBeDisabled();
  await slot("broll").getByRole("button", { name: "Choose b-roll" }).click();
  await page.getByRole("dialog").getByRole("option").first().click();
  await expect(slot("broll")).toHaveAttribute("data-status", "ready");

  await slot("before").getByRole("heading", { name: "Before" }).click();
  await page.getByTestId("caption-pick").click();
  await page
    .getByRole("dialog", { name: "Choose a caption" })
    .getByRole("option", { name: new RegExp(BANK_TEXT) })
    .click();
  await expect(page.getByTestId("caption-text")).toHaveValue(BANK_TEXT);
  await expect(exportButton()).toBeEnabled();
}

// Clicks Export and waits for the done panel. Returns the exported file name.
async function exportAndWait(): Promise<string> {
  await exportButton().click();
  const progress = page.getByRole("dialog", { name: "Exporting your video" });
  await expect(progress).toBeVisible();
  await expect(progress.getByRole("progressbar")).toBeVisible();
  const done = page.getByRole("dialog", { name: "Your video is ready" });
  await expect(done).toBeVisible({ timeout: 240_000 });
  return (await done.getByTestId("export-file-name").textContent()) ?? "";
}

function exportedFiles(): { folder: string; names: string[] } {
  const productDir = path.join(launched.libraryDir, "exports", SLUG);
  const [dateDir] = readdirSync(productDir);
  const folder = path.join(productDir, dateDir ?? "");
  return { folder, names: readdirSync(folder).sort() };
}

test("export two videos with the same hook: files, sidecars, _02, verify", async () => {
  test.setTimeout(600_000);

  await test.step("set up a product with b-roll and one bank caption", async () => {
    // Replace the native Show in Finder so the test can see the call.
    await launched.app.evaluate(({ shell }) => {
      const calls: string[] = [];
      (globalThis as { __revealed?: string[] }).__revealed = calls;
      shell.showItemInFolder = (p: string) => {
        calls.push(p);
      };
    });
    await page.getByRole("button", { name: "Choose another folder" }).click();
    await page.getByRole("button", { name: "Use this folder" }).click();
    await page.getByRole("button", { name: "Add your first product" }).click();
    const dialog = page.getByRole("dialog", { name: "Add product" });
    await dialog.getByLabel("Full name").fill(FULL);
    await dialog.getByRole("button", { name: "Add product" }).click();
    await expect(dialog).toBeHidden();
    await page
      .getByRole("listitem")
      .filter({ hasText: FULL })
      .getByRole("button", { name: new RegExp(FULL) })
      .first()
      .click();
    await page.getByLabel("B-roll files").setInputFiles([CLIP]);
    await expect(page.getByTestId("broll-duration")).toHaveCount(1, {
      timeout: 90_000,
    });
    await page.evaluate(async (text) => {
      const [product] = await window.api.products.list();
      const created = await window.api.captions.create({
        text,
        slot: "before",
        productId: product.id,
      });
      if (!created.ok) {
        throw new Error(created.message);
      }
    }, BANK_TEXT);
  });

  let first = "";
  await test.step("export the first video", async () => {
    await nav("New Video");
    await page.getByRole("option", { name: new RegExp(FULL) }).click();
    await buildVideo();
    first = await exportAndWait();
    expect(first).toMatch(
      /^levis-501-jeans_cant-fix-my-smile_\d{4}-\d{2}-\d{2}_01\.mp4$/,
    );
  });

  await test.step("Show in Finder asks main to reveal the file from the row", async () => {
    await page
      .getByRole("button", { name: /^Show in (Finder|Explorer)$/ })
      .click();
    await expect
      .poll(() =>
        launched.app.evaluate(
          () => (globalThis as { __revealed?: string[] }).__revealed ?? [],
        ),
      )
      .toEqual([path.join(exportedFiles().folder, first)]);
  });

  await test.step("New video, same product opens an empty draft", async () => {
    await page.getByRole("button", { name: "New video, same product" }).click();
    await expect(slot("before")).toHaveAttribute("data-status", "empty");
    await expect(slot("after")).toHaveAttribute("data-status", "empty");
    await expect(slot("broll")).toHaveAttribute("data-status", "empty");
  });

  let second = "";
  await test.step("the same hook on the same day gets _02", async () => {
    await buildVideo();
    second = await exportAndWait();
    expect(second).toBe(first.replace(/_01\.mp4$/, "_02.mp4"));
  });

  await test.step("both mp4 files and sidecars are on disk", async () => {
    const { names } = exportedFiles();
    const base1 = first.replace(/\.mp4$/, "");
    const base2 = second.replace(/\.mp4$/, "");
    expect(names).toEqual(
      [
        `${base1}.mp4`,
        `${base1}.recipe.json`,
        `${base2}.mp4`,
        `${base2}.recipe.json`,
      ].sort(),
    );
  });

  await test.step("the database says exported, and the caption was counted twice", async () => {
    const state = await page.evaluate(async () => {
      const videos = await window.api.videos.list({ status: "exported" });
      const captions = await window.api.captions.list();
      return {
        paths: videos.map((v) => v.exportPath).sort(),
        counts: captions.map((c) => c.useCount),
      };
    });
    expect(state.paths).toHaveLength(2);
    expect(state.paths.every((p) => p?.startsWith(`exports/${SLUG}/`))).toBe(
      true,
    );
    expect(state.counts).toEqual([2]);
  });

  await test.step("npm run verify:render passes on the exported file with its sidecar", async () => {
    const { folder } = exportedFiles();
    const mp4 = path.join(folder, first);
    const sidecar = mp4.replace(/\.mp4$/, ".recipe.json");
    const recipe = JSON.parse(readFileSync(sidecar, "utf8")) as {
      productSlug: string;
    };
    expect(recipe.productSlug).toBe(SLUG);
    // Sidecar media paths are relative to the library, not to the sidecar's folder.
    const output = execFileSync(
      "npm",
      [
        "run",
        "verify:render",
        "--",
        mp4,
        "--recipe",
        sidecar,
        "--media-root",
        launched.libraryDir,
      ],
      { encoding: "utf8" },
    );
    expect(output).toContain("PASS");
  });

  await test.step("nothing is left in cache/tmp", async () => {
    const tmp = path.join(launched.libraryDir, "cache", "tmp");
    expect(existsSync(tmp) ? readdirSync(tmp) : []).toEqual([]);
  });
});
